-- Controller registry: definitions (art + button anchors) by id.
-- Definitions.lua is generated by tools/art; this file only reads it.
local _, ns = ...

local Registry = {}
ns.Controllers = ns.Controllers or {}
ns.Controllers.Registry = Registry

local defs = {} ---@type table<string, table>
local order = {} ---@type string[]

---@param def table { id, name, family, labelStyle, texture, aspect, anchors, hidden }
function Registry.Register(def)
    assert(type(def.id) == "string", "controller id required")
    assert(type(def.anchors) == "table", def.id .. ": anchors required")
    if not defs[def.id] then
        order[#order + 1] = def.id
    end
    defs[def.id] = def
end

---@return table|nil
function Registry.Get(id)
    return defs[id]
end

---Controllers in registration order. Back views are extra definitions
---(view = "back") that belong to a front one; they are left out unless asked for.
---@param withViews? boolean include back views
---@return table[]
function Registry.All(withViews)
    local out = {}
    for _, id in ipairs(order) do
        if withViews or defs[id].view ~= "back" then
            out[#out + 1] = defs[id]
        end
    end
    return out
end

---The back view of a controller (nil when it has none).
---@return table|nil
function Registry.BackOf(def)
    return def and def.back and defs[def.back] or nil
end

---The definition showing `button`: the front, or the back view for back buttons.
---@return table|nil def, string|nil view "front" | "back"
function Registry.ViewFor(def, button)
    if def.anchors[button] or (button:match("^PADD[UDLR]") and def.anchors.PADDPAD) then
        return def, "front"
    end
    local back = Registry.BackOf(def)
    if back and back.anchors[button] then
        return back, "back"
    end
end

---Anchor of a button on a definition, in 0..1 image coordinates.
---Falls back from a single D-pad direction to the whole D-pad.
---@return { x: number, y: number, w: number, h: number }|nil
function Registry.Anchor(def, button)
    local a = def.anchors[button]
    if not a and button:match("^PADD") then
        a = def.anchors.PADDPAD
    end
    return a
end

---Buttons on the controller the game cannot see (back grips, paddles, touchpad...).
---@return boolean
function Registry.IsHidden(def, button)
    for _, b in ipairs(def.hidden or {}) do
        if b == button then
            return true
        end
    end
    return false
end
